# fill marker cells from the nearest non-marker cell (Manhattan distance; favor most common on ties)
f=arr.copy()
for i,j in zip(*np.where(arr==1)):
    best=99; vals=[]
    for r in range(30):
      for c in range(30):
       if arr[r,c]!=1:
        d=abs(r-i)+abs(c-j)
        if d<best: best=d; vals=[int(arr[r,c])]
        elif d==best: vals.append(int(arr[r,c]))
    from collections import Counter
    f[i,j]=Counter(vals).most_common(1)[0][0]
mapping={0:3,1:0,2:0,3:9,4:7,6:6,7:9,8:4,9:9}
